  title: "Underground Mining",
  summary:
    "Underground mining, also called sub-surface mining, is the extraction of minerals from deposits below the ground surface through underground workings. It is considered when the depth, geometry, rock conditions, ore value, and cost make underground extraction suitable or more economical than surface mining.",

