        "Gravity separation has the advantages of being a low-cost and simple process.",
        "Gravity separation is a key stage in the separation of alluvial gold.",
        "The notes identify the jig, shaking table and spiral chute as equipment used in gravity separation to discharge much of the waste rock and obtain a coarse-grain concentrate."
