        "Examples include earthquakes, volcanic eruptions, landslides, rockfalls, ground subsidence, sinkholes, tsunamis and other forms of mass movement.",
        "The occurrence of a geologic hazard does not automatically mean that a disaster will occur. The severity of the resulting disaster depends partly on exposure, vulnerability and the ability of people and institutions to respond.",
