        "Under PPL, the lecturer identifies colour, relief, refractive index, cleavage, habit, pleochroism and absorption.",
        "Under XPL, the lecturer introduces isotropic and anisotropic behaviour, double refraction or birefringence, interference colours, extinction and twinning.",
